AWS Application Load Balancer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS Application Load Balancer container

Container_Boundary(aws_application_load_balancer, "AWS Application Load Balancer") {
    Component(ingress_router_and_tls_terminator, "Ingress Router and TLS Terminator", "AWS ALB Listener", "Terminates mTLS and HTTPS traffic from payment processors and fraud analysts, performing initial edge checks.")
    Component(scoring_traffic_router, "Scoring Traffic Router", "HTTP/2 Path-Based Router", "Routes payment authorization scoring traffic to the Scoring Engine via HTTP/2 on /v1/score.")
    Component(administrative_traffic_router, "Administrative Traffic Router", "HTTP/1.1 Path-Based Router", "Routes case management and rule update traffic to the Case Management Backend on /v1/cases/*.")
}

Rel(ingress_router_and_tls_terminator, scoring_traffic_router, "Forwards validated scoring requests", "")
Rel(ingress_router_and_tls_terminator, administrative_traffic_router, "Forwards validated administrative and case management requests", "")

@enduml

Auditor Query Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(auditor_query_service, "Auditor Query Service") {
    Component(api_controller, "API Controller", "Node.js / TypeScript container on AWS Fargate", "Receives secure queries from compliance officers and validates JWTs.")
    Component(query_translator, "Query Translator", "Stateless TypeScript component", "Translates audit queries into parameterized SQL.")
    Component(athena_client, "Athena Client", "AWS SDK", "Executes parameterized SQL queries against AWS Athena.")
}

Rel(api_controller, query_translator, "Invoke report generation", "In-process calls")
Rel(query_translator, athena_client, "Execute parameterized SQL", "AWS SDK / HTTPS")
@enduml

Amazon DynamoDB.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_dynamodb, "Amazon DynamoDB") {
    Component(Feature_Store_Table, "Feature Store Table", "DynamoDB Table", "Stores low-latency risk profiles for real-time payment fraud screening.")
    Component(Case_State_Table, "Case State Table", "DynamoDB Table", "Manages investigation workflow states for analyst case reviews.")
    Component(Audit_Stream_Processor, "Audit Stream Processor", "DynamoDB Stream / AWS Lambda", "Asynchronously captures state changes for auditability without impacting transaction latency.")
}

Rel(Case_State_Table, Audit_Stream_Processor, "Publishes state changes", "DynamoDB Streams")

@startuml

Amazon SQS / SNS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_sqs_sns, "Amazon SQS / SNS") {
    Component(FraudEventTopic, "FraudEventTopic", "Amazon SNS", "Publishes authorization and decision events from the Scoring Engine.")
    Component(AuditLogQueue, "AuditLogQueue", "Amazon SQS", "Receives payloads from FraudEventTopic for audit logging via AWS PrivateLink.")
    Component(CaseRoutingQueue, "CaseRoutingQueue", "Amazon SQS", "Receives review tasks from FraudEventTopic to route to the Case Management Backend.")
    Component(Dead_Letter_Queues_DLQ, "Dead-Letter Queues (DLQ)", "Amazon SQS DLQ", "Prevents poison-pill message processing loops with a maximum receive count limit.")
}

Rel(FraudEventTopic, AuditLogQueue, "Pushes payloads to", "SQS protocol over AWS PrivateLink")
Rel(FraudEventTopic, CaseRoutingQueue, "Pushes payloads to", "SQS protocol over AWS PrivateLink")

@enduml
